#include <bits/stdc++.h>
using namespace std;

#define fastio ios::sync_with_stdio(false), cin.tie(nullptr)

using ll = long long;

const ll INF = 1000000000000000000LL;

ll f, T, t0, a1, t1, p1, a2, t2, p2;

bool ok(ll mid, ll tempo, ll falta) {
    return min(falta, mid * a2) * t2
           + t0 * max(0LL, falta - mid * a2) <= tempo;
}

ll solve(ll tempo, ll falta) {
    if (falta * t0 <= tempo) return 0;

    ll bot = 0, top = falta;

    while (top - bot > 1) {
        ll mid = (top + bot) >> 1;
        if (ok(mid, tempo, falta))
            top = mid;
        else
            bot = mid;
    }

    if (ok(bot, tempo, falta)) top = bot;
    if (!ok(top, tempo, falta)) return -1;

    return top * p2;
}

int main() {
    fastio;

    cin >> f >> T >> t0;
    cin >> a1 >> t1 >> p1;
    cin >> a2 >> t2 >> p2;

    ll ans = INF;

    for (ll i = 0; i <= INF; ++i) {
        if (min(f, i * a1) * t1 > T) break;

        ll x = solve(max(0LL, T - i * a1 * t1),
                     max(0LL, f - i * a1));

        if (x != -1) ans = min(ans, i * p1 + x);

        if ((i - 1) * a1 > f) break;
    }

    if (ans == INF) ans = -1;
    cout << ans << '\n';

    return 0;
}

